// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address callerAddr, address other) public {
        vm.assume(callerAddr != address(0));

        uint256 td_before = c.totalDistributed();

        bool ok;
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        address owner = address(this);
        uint256 ownerBal = c.balanceOf(owner);
        uint256 td_after = c.totalDistributed();

        assertTrue(!ok || ownerBal == td_after);
    }
}
